{"description":"Compute Tm profiles for candidate annealing regions","cmd":"cat > tm_profiles.py <<'PY'
import subprocess, sys

def oligotm(seq):
    r = subprocess.run(['oligotm','-tp','1','-sc','1','-mv','50','-dv','2','-n','0.8','-d','500',seq],
                       capture_output=True, text=True)
    try:
        return float(r.stdout.strip())
    except:
        return None

seqs={}; name=None
for line in open('sequences.fasta'):
    line=line.strip()
    if not line: continue
    if line.startswith('>'):
        name=line[1:].strip(); seqs[name]=''
    else:
        seqs[name]+=line.upper()

rc = lambda s: s.translate(str.maketrans('ACGT','TGCA'))[::-1]

# Define retained segments and boundaries
# egfp retained = seq[4:714]; flag retained = seq[3:87]; snap retained = seq[3:546]
# vector forward annealing starts at input[687]; vector reverse annealing = rc(input[210-L : 210])
frags = {
 'egfp': {'start':4, 'end':714, 'tplate':'egfp'},
 'flag': {'start':3, 'end':87, 'tplate':'flag'},
 'snap': {'start':3, 'end':546, 'tplate':'snap'},
 'input': {'start':687, 'end':214+len(seqs['input']), 'tplate':'input', 'is_vector':True},
}
# For vector, retained sequence is input[687:] + input[:214]; forward annealing at input[687:], reverse annealing rc(input[210-L:210])
print("Template name -> forward annealing start index, reverse annealing window end index")
print("egfp fwd start",4, " rev window end", 710)
print("flag fwd start",3, " rev window end", 83)
print("snap fwd start",3, " rev window end", 542)
print("input fwd start",687, " rev window end", 210)
print()

# Build forward annealing oligos: template[start : start+L]
def fwd_oligo(tplate, start, L):
    return seqs[tplate][start:start+L]

def rev_oligo(tplate, end, L):
    # annealing = rc(template[end-L : end])
    return rc(seqs[tplate][end-L:end])

# For vector reverse, the template region is in input (linear). Since vector retained end is ATGA at input[210:214],
# rev window ends at 210.
for name, (fstart, rend, tplate) in {
    'egfp': (4, 710, 'egfp'),
    'flag': (3, 83, 'flag'),
    'snap': (3, 542, 'snap'),
    'input': (687, 210, 'input'),
}.items():
    print('===',name,'===')
    for kind in ('fwd','rev'):
        listp=[]
        for L in range(15,37):
            seq = fwd_oligo(tplate, fstart, L) if kind=='fwd' else rev_oligo(tplate, rend, L)
            tm = oligotm(seq)
            listp.append((L, tm, seq))
        print(kind)
        for L,tm,seq in listp:
            if tm is not None:
                print(f' L={L:2d} Tm={tm:6.2f}  {seq[:20]}...')
            else:
                print(f' L={L:2d} Tm=   none {seq}')
        print()
PY
