{"description":"Verify sites in primers","cmd":"python3 - <<'PY'
for line in open('primers.fasta'):
    s=line.strip()
    if s.startswith('>'):
        name=s
        continue
    if name.endswith('_fwd'):
        ok = s.startswith('GGTCTC')
        print(name, 'site GGTCTC at start:', ok, 'seq', s[:20])
    else:
        # reverse: tail = 4bp ov + GAGACC
        ok = s[:4] in ('TCAT','TTTG','TGAA','ACCC') and s[4:10]=='GAGACC'
        print(name, 'ov+revcomp site at 5\' end:', ok, 'tail', s[:10], 'seq', s[:20])
