{"description":"Check for internal BsaI sites in full primers","cmd":"python3 - <<'PY'
for line in open('primers.fasta'):
    s=line.strip()
    if s.startswith('>'): name=s; continue
    hits=[]
    # designed site: for fwd first 6 = GGTCTC; for rev positions 5-10 = GAGACC (indices 4..10)
    # find all occurrences
    for motif in ['GGTCTC','GAGACC']:
        start=0
        while True:
            i=s.find(motif,start)
            if i<0: break
            hits.append((i,motif))
            start=i+1
    designed=[]
    for i,m in hits:
        if name.endswith('_fwd') and i==0 and m=='GGTCTC': designed.append((i,m))
        elif name.endswith('_rev') and i==4 and m=='GAGACC': designed.append((i,m))
    extras=[h for h in hits if h not in designed]
    print(name, 'extra BsaI hits:', extras if extras else 'none')
PY"}

